// Calendly returned - map its response into something the voice AI can say out loud.
const res = $input.first().json;
const status = res.statusCode;
const body = res.body || {};
const detail = body.message || body.title || '';

if (status >= 200 && status < 300) {
  return [{
    json: {
      ok: true,
      message: 'Booked successfully. A confirmation email is on its way.',
      cancel_url: body.resource?.cancel_url || body.cancel_url,
      reschedule_url: body.resource?.reschedule_url || body.reschedule_url,
      event: body.resource?.event || body.event,
    },
  }];
}

// Only call it a taken slot when Calendly actually says so. A blanket 400 = slot taken guess hid a real form error before.
const slotGone = status === 409 || ((status === 400 || status === 404) && /not available|no longer|unavailable|already|slot/i.test(detail));

if (slotGone) {
  return [{ json: { ok: false, retryable: true, status, detail, message: "That time just became unavailable. Let's check availability again and pick another slot." } }];
}

return [{
  json: {
    ok: false,
    retryable: false,
    status,
    detail,
    message: "I couldn't complete the booking due to a technical issue. I'll take your details and have someone follow up.",
  },
}];
